class Scoreboard:
    def __init__(self):
        self.scores = {}

    def add(self, player, points):
        self.scores[player] = self.scores.get(player, 0) + points

    def score(self, player):
        return self.scores.get(player, 0)

    def leader(self):
        if not self.scores:
            return None
        return min(self.scores, key=lambda p: (-self.scores[p], p))

